    "explanation": "正解は「借入れには通常、所定の利息が発生する」です。契約者貸付は解約返戻金等を基礎として扱うため、解約返戻金がない契約すべてで死亡保険金を上限に使えるものではありません。原則無利息でもなく、貸付利用に先立って契約自体を解約する必要もありません。 貸付中も一般に保障は継続しますが、未返済の元金・利息は死亡保険金等から差し引かれます。元利金が解約返戻金を超え、所定の対応をしない場合には失効することがあるため、利用可能額・利率・返済条件を確認します。",
